mapper.select:
select * from ( select inner_table.*, ROWNUM rn from ( select e.exam_no, e.course_no, c.course_title, e.exam_title, e.exam_start, e.exam_end, e.exam_limit, e.exam_status,
case when e.exam_status = '마감' or systimestamp >= e.exam_end then '종료'
when systimestamp < e.exam_start then '예정'
else '응시가능' end as exam_phase,
att.attempt_no, att.attempt_status, att.attempt_submit, att.attempt_score
from exam e
join course c on e.course_no = c.course_no
join student_course sc on e.course_no = sc.course_no
left join attempt att on e.exam_no = att.exam_no and att.student_no = #{studentNo}
order by e.exam_start desc, e.exam_no desc
) inner_table
where ROWNUM <= #{endRow} )
where rn >= #{beginRow}

mapper.update:
update exam
set exam_status = '마감'
where exam_no = #{examNo}
